// Small DOM helpers. Text from data is always set as text, never as HTML.

/**
 * el('button', { class: 'btn', onclick: fn, style: { '--x': '1' } }, 'Label', child)
 * `html` is only for SVG strings generated by js/art (no data inside).
 */
export function el(tag, props = {}, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(props)) {
    if (value == null || value === false) continue;
    if (key === 'class') node.className = value;
    else if (key === 'text') node.textContent = value;
    else if (key === 'html') node.innerHTML = value;
    else if (key === 'style') for (const [p, v] of Object.entries(value)) node.style.setProperty(p, v);
    else if (key.startsWith('on')) node.addEventListener(key.slice(2), value);
    else node.setAttribute(key, value === true ? '' : value);
  }
  for (const child of children.flat()) {
    if (child == null || child === false) continue;
    node.append(child instanceof Node ? child : String(child));
  }
  return node;
}

/** Replace a container's content and move focus to its heading for screen readers and keyboards. */
export function mount(root, ...nodes) {
  root.replaceChildren(...nodes);
  root.querySelector('[data-autofocus]')?.focus({ preventScroll: true });
  window.scrollTo(0, 0);
}

/** Polite screen-reader announcement. */
export function announce(text) {
  const region = document.getElementById('announcer');
  if (!region) return;
  region.textContent = '';
  // A fresh write after clearing makes repeated messages get announced.
  setTimeout(() => { region.textContent = text; }, 30);
}
